/* Baskervville — locally embedded (no Google Fonts request, GDPR-safe).
   Source: Google Fonts v20, OFL license. Latin subset, base64-inlined. */
@font-face {
  font-family: 'Baskervville';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url(data:font/woff2;base64,) format('woff2');
}
@font-face {
  font-family: 'Baskervville';
  font-style: italic;
  font-weight: 400;
  font-display: swap;
  src: url(data:font/woff2;base64,) format('woff2');
}
